CREATE TABLE IF NOT EXISTS AUTHENTICATION (ID BIGINT AUTO_INCREMENT PRIMARY KEY, USER_ID BIGINT NOT NULL, EMAIL VARCHAR(320) NOT NULL, CREATED_AT DATETIME(9) NOT NULL, UPDATED_AT DATETIME(9) NOT NULL);
ALTER TABLE AUTHENTICATION ADD CONSTRAINT AUTHENTICATION_USER_ID_UNIQUE UNIQUE (USER_ID);
CREATE TABLE IF NOT EXISTS AUTH_DEVICE (ID BIGINT AUTO_INCREMENT PRIMARY KEY, USER_AUTH_ID BIGINT NOT NULL, DEVICE_UUID VARCHAR(128) NOT NULL, DEVICE_NAME VARCHAR(255) NOT NULL, REFRESH_TOKEN VARCHAR(255) NULL, IS_SIGNED_IN BOOLEAN NOT NULL, CREATED_AT DATETIME(9) NOT NULL, UPDATED_AT DATETIME(9) NOT NULL, CONSTRAINT FK_AUTH_DEVICE_USER_AUTH_ID__ID FOREIGN KEY (USER_AUTH_ID) REFERENCES AUTHENTICATION(ID) ON DELETE CASCADE ON UPDATE RESTRICT);
CREATE INDEX AUTH_DEVICE_USER_AUTH_ID ON AUTH_DEVICE (USER_AUTH_ID);
ALTER TABLE AUTH_DEVICE ADD CONSTRAINT AUTH_DEVICE_DEVICE_UUID_UNIQUE UNIQUE (DEVICE_UUID);
CREATE TABLE IF NOT EXISTS PASSKEY_CREDENTIALS (ID BIGINT AUTO_INCREMENT PRIMARY KEY, AUTH_ID BIGINT NOT NULL, HANDLE VARBINARY(64) NOT NULL, CRED_DESCRIPTOR_ID VARBINARY(255) NOT NULL, CRED_DESCRIPTOR_TYPE VARCHAR(255) NOT NULL, CRED_DESCRIPTOR_TRANSPORTS VARCHAR(255) NOT NULL, PUBLIC_KEY VARCHAR(255) NOT NULL, SIGNATURE_COUNT BIGINT NOT NULL, DISCOVERABLE BOOLEAN NOT NULL, BACKUP_ELIGIBLE BOOLEAN NOT NULL, BACKED_UP BOOLEAN NOT NULL, ATTESTATION_OBJECT VARBINARY(255) NOT NULL, CLIENT_DATA VARBINARY(255) NOT NULL, CREATED_AT DATETIME(9) NOT NULL, UPDATED_AT DATETIME(9) NOT NULL, CONSTRAINT FK_PASSKEY_CREDENTIALS_AUTH_ID__ID FOREIGN KEY (AUTH_ID) REFERENCES AUTHENTICATION(ID) ON DELETE CASCADE ON UPDATE RESTRICT);
